MAX_R = 998
def try_candidates():
    attempted = 0
    # As per spec, do up to 10 per connection
    guess_block = []
    for r in range(MAX_R+1):
        num = ct_total - 123 - r
        if num % 999 != 0:
            continue
        candidate = num // 999
        if candidate <= 0:
